parameters.jsCode:
const topic = $('Extract Topic & Chat ID').item.json.topic;
const chatId = $('Extract Topic & Chat ID').item.json.chatId;
const username = $('Extract Topic & Chat ID').item.json.username;

// Extract text from Groq response structure: choices[0].message.content
const agent1 = $('Agent 1 - Web Research').item.json.choices[0].message.content;
const agent2 = $('Agent 2 - Statistics Finder').item.json.choices[0].message.content;
const agent3 = $('Agent 3 - Expert Insights').item.json.choices[0].message.content;

return [{
  json: {
    chatId,
    username,
    topic,
    webResearch: agent1,
    statistics: agent2,
    expertInsights: agent3
  }
}];

// Extract final report from Groq response
const report = $('Agent 4 - Report Compiler').item.json.choices[0].message.content;
const chatId = $('Merge All Agent Outputs').item.json.chatId;
const topic = $('Merge All Agent Outputs').item.json.topic;

// Split report into chunks of 4000 chars for Telegram's message limit
const chunkSize = 4000;
const chunks = [];
for (let i = 0; i < report.length; i += chunkSize) {
  chunks.push(report.substring(i, i + chunkSize));
}

return chunks.map((chunk, index) => ({
  json: {
    chatId,
    topic,
    chunk,
    partNumber: index + 1,
    totalParts: chunks.length,
    isFirst: index === 0,
    isLast: index === chunks.length - 1,
    fullReport: report
  }
}));

